import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry triplet_margin_kernel(
    .param .u64 anchor_ptr,
    .param .u64 pos_ptr,
    .param .u64 neg_ptr,
    .param .u64 out_ptr,
    .param .u64 block_sums_ptr,
    .param .u64 counter_ptr,
    .param .u32 batch_size,
    .param .u32 dim_size,
    .param .f32 margin,
    .param .f32 eps
)
{
    .reg .pred  %p<12>;
    .reg .b32   %r<64>;
    .reg .b64   %rd<48>;
    .reg .f32   %f<64>;
    .shared .align 4 .b8 shmem[4096];
    // Load parameters
    ld.param.u64 %rd1, [anchor_ptr];
    ld.param.u64 %rd2, [pos_ptr];
    ld.param.u64 %rd3, [neg_ptr];
    ld.param.u64 %rd4, [out_ptr];
    ld.param.u64 %rd5, [block_sums_ptr];
    ld.param.u64 %rd6, [counter_ptr];
    ld.param.u32 %r20, [batch_size];
    ld.param.u32 %r21, [dim_size];
    ld.param.f32 %f20, [margin];
    ld.param.f32 %f21, [eps];
    // Thread/block info
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %nctaid.x;
    // lane and warp identifiers
    mov.u32 %r24, %laneid;                 // lane id
    shr.u32 %r25, %r0, 5;                  // warp id within block
    add.u32 %r27, %r2, 31;                 // warps per block = (blockDim + 31) >> 5
    shr.u32 %r27, %r27, 5;
    // global warp id = blockIdx.x * warpsPerBlock + warpId
    mad.lo.s32 %r28, %r1, %r27, %r25;
    // total warps in grid = gridDim.x * warpsPerBlock
    mul.lo.u32 %r29, %r3, %r27;
    // Local accumulator for this thread (lane 0 will accumulate)
    mov.f32 %f0, 0f00000000;
    // Mask for shfl
    mov.u32 %r26, 0xffffffff;
    // i loop over batch with warp-stride
    mov.u32 %r4, %r28;                     // i = globalWarpId
LOOP_I:
    setp.ge.u32 %p0, %r4, %r20;
    @%p0 bra LOOP_I_END;
    // base offset in elements = i * dim_size
    mul.wide.u32 %rd10, %r4, %r21;         // 64-bit product
    shl.b64 %rd11, %rd10, 2;               // bytes offset (*4)
    add.s64 %rd12, %rd1, %rd11;            // ptrA base
    add.s64 %rd13, %rd2, %rd11;            // ptrP base
    add.s64 %rd14, %rd3, %rd11;            // ptrN base
    // Vectorized per-lane accumulation over dim using warp-stride in v4 units
    mov.f32 %f1, 0f00000000;               // sumAP local
    mov.f32 %f2, 0f00000000;               // sumAN local
    // vec4 count and scalar remainder
    shr.u32 %r22, %r21, 2;                 // vec4_count = dim >> 2
    and.b32 %r23, %r21, 3;                 // rem_scalar = dim & 3
    mov.u32 %r30, %r24;                    // v = lane
LOOP_V4:
    setp.ge.u32 %p1, %r30, %r22;
    @%p1 bra LOOP_V4_END;
    // byte offset for v4 = v * 16
    mul.wide.u32 %rd15, %r30, 16;
    add.s64 %rd16, %rd12, %rd15;           // a addr
    add.s64 %rd17, %rd13, %rd15;           // p addr
    add.s64 %rd18, %rd14, %rd15;           // n addr
    ld.global.cs.v4.f32 {%f3,%f4,%f5,%f6},  [%rd16];
    ld.global.cs.v4.f32 {%f7,%f8,%f9,%f10}, [%rd17];
    ld.global.cs.v4.f32 {%f11,%f12,%f13,%f14}, [%rd18];
    // (a - p)^2 accumulate
    sub.f32 %f15, %f3, %f7;
    fma.rn.f32 %f1, %f15, %f15, %f1;
    sub.f32 %f16, %f4, %f8;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f5, %f9;
    fma.rn.f32 %f1, %f17, %f17, %f1;
    sub.f32 %f18, %f6, %f10;
    fma.rn.f32 %f1, %f18, %f18, %f1;
    // (a - n)^2 accumulate
    sub.f32 %f19, %f3, %f11;
    fma.rn.f32 %f2, %f19, %f19, %f2;
    sub.f32 %f22, %f4, %f12;
    fma.rn.f32 %f2, %f22, %f22, %f2;
    sub.f32 %f23, %f5, %f13;
    fma.rn.f32 %f2, %f23, %f23, %f2;
    sub.f32 %f24, %f6, %f14;
    fma.rn.f32 %f2, %f24, %f24, %f2;
    add.u32 %r30, %r30, 32;                // v += warpSize
    bra LOOP_V4;
LOOP_V4_END:
    // Scalar tail processed by lane 0 only
    setp.eq.u32 %p2, %r24, 0;              // lane0?
    @!%p2 bra SKIP_SCALAR_TAIL;
    setp.eq.u32 %p3, %r23, 0;
    @%p3 bra SKIP_SCALAR_TAIL;
    // start index = dim - rem
    sub.u32 %r31, %r21, %r23;
    mul.wide.u32 %rd19, %r31, 4;
    add.s64 %rd20, %rd12, %rd19;
    add.s64 %rd21, %rd13, %rd19;
    add.s64 %rd22, %rd14, %rd19;
    mov.u32 %r32, 0;
SCALAR_TAIL_LOOP:
    setp.ge.u32 %p4, %r32, %r23;
    @%p4 bra SCALAR_TAIL_END;
    ld.global.cs.f32 %f3, [%rd20];
    ld.global.cs.f32 %f4, [%rd21];
    ld.global.cs.f32 %f5, [%rd22];
    sub.f32 %f6, %f3, %f4;
    fma.rn.f32 %f1, %f6, %f6, %f1;
    sub.f32 %f7, %f3, %f5;
    fma.rn.f32 %f2, %f7, %f7, %f2;
    add.u32 %r32, %r32, 1;
    add.s64 %rd20, %rd20, 4;
    add.s64 %rd21, %rd21, 4;
    add.s64 %rd22, %rd22, 4;
    bra SCALAR_TAIL_LOOP;
SCALAR_TAIL_END:
SKIP_SCALAR_TAIL:
    // Warp reduction of sums (sumAP in %f1, sumAN in %f2)
    shfl.sync.down.b32 %f40, %f1, 16, 0x1f, %r26;
    add.f32 %f1, %f1, %f40;
    shfl.sync.down.b32 %f40, %f1, 8, 0x1f, %r26;
    add.f32 %f1, %f1, %f40;
    shfl.sync.down.b32 %f40, %f1, 4, 0x1f, %r26;
    add.f32 %f1, %f1, %f40;
    shfl.sync.down.b32 %f40, %f1, 2, 0x1f, %r26;
    add.f32 %f1, %f1, %f40;
    shfl.sync.down.b32 %f40, %f1, 1, 0x1f, %r26;
    add.f32 %f1, %f1, %f40;
    shfl.sync.down.b32 %f41, %f2, 16, 0x1f, %r26;
    add.f32 %f2, %f2, %f41;
    shfl.sync.down.b32 %f41, %f2, 8, 0x1f, %r26;
    add.f32 %f2, %f2, %f41;
    shfl.sync.down.b32 %f41, %f2, 4, 0x1f, %r26;
    add.f32 %f2, %f2, %f41;
    shfl.sync.down.b32 %f41, %f2, 2, 0x1f, %r26;
    add.f32 %f2, %f2, %f41;
    shfl.sync.down.b32 %f41, %f2, 1, 0x1f, %r26;
    add.f32 %f2, %f2, %f41;
    // lane 0 computes loss and accumulates to f0
    setp.ne.u32 %p5, %r24, 0;
    @%p5 bra SKIP_LOSS_ACCUM;
    add.f32 %f8, %f1, %f21;               // sumAP + eps
    add.f32 %f9, %f2, %f21;               // sumAN + eps
    sqrt.rn.f32 %f10, %f8;                // d_ap
    sqrt.rn.f32 %f11, %f9;                // d_an
    sub.f32 %f12, %f10, %f11;             // d_ap - d_an
    add.f32 %f13, %f12, %f20;             // + margin
    max.f32 %f13, %f13, 0f00000000;       // relu
    add.f32 %f0, %f0, %f13;               // local_sum += loss_i
SKIP_LOSS_ACCUM:
    add.u32 %r4, %r4, %r29;               // i += totalWarps
    bra LOOP_I;
LOOP_I_END:
    // Warp-level reduction using shfl to compute block sum (f0 has per-lane sums; only lane0 has nonzero)
    shfl.sync.down.b32 %f24, %f0, 16, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 8, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 4, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 2, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 1, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    // lane 0 of each warp writes its partial sum
    setp.ne.u32 %p6, %r24, 0;
    @%p6 bra SKIP_WARP_STORE;
    mov.u64 %rd23, shmem;
    mul.wide.u32 %rd24, %r25, 4;
    add.s64 %rd25, %rd23, %rd24;
    st.shared.f32 [%rd25], %f0;
SKIP_WARP_STORE:
    bar.sync 0;
    // number of warps in block already in %r27
    // only warp 0 performs final reduce over warp sums
    setp.ne.u32 %p7, %r25, 0;
    @%p7 bra AFTER_FINAL_REDUCE;
    // load warp sums into first warp lanes
    mov.f32 %f0, 0f00000000;
    setp.ge.u32 %p8, %r24, %r27;
    @%p8 bra SKIP_LOAD_WARP_SUM;
    mov.u64 %rd26, shmem;
    mul.wide.u32 %rd27, %r24, 4;
    add.s64 %rd28, %rd26, %rd27;
    ld.shared.f32 %f0, [%rd28];
SKIP_LOAD_WARP_SUM:
    shfl.sync.down.b32 %f24, %f0, 16, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 8, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 4, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 2, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
    shfl.sync.down.b32 %f24, %f0, 1, 0x1f, %r26;
    add.f32 %f0, %f0, %f24;
AFTER_FINAL_REDUCE:
    // Thread 0 writes block sum and participates in global reduction
    mov.f32 %f17, %f0;
    setp.ne.u32 %p9, %r0, 0;
    @%p9 bra K_EXIT;
    // store to block_sums[blockIdx.x]
    mul.wide.u32 %rd31, %r1, 4;
    add.s64 %rd32, %rd5, %rd31;
    st.global.f32 [%rd32], %f17;
    // ensure visibility before incrementing counter
    membar.gl;
    // atomic increment: old = atomicAdd(counter, 1)
    atom.global.add.u32 %r9, [%rd6], 1;
    // if old == gridDim - 1, this is the last block
    sub.u32 %r10, %r3, 1;
    setp.eq.u32 %p10, %r9, %r10;
    @!%p10 bra K_EXIT;
    // Last block does final sum and write mean
    mov.f32 %f18, 0f00000000;
    mov.u32 %r11, 0;
FINAL_SUM_LOOP:
    setp.ge.u32 %p11, %r11, %r3;
    @%p11 bra FINAL_SUM_END;
    mul.wide.u32 %rd33, %r11, 4;
    add.s64 %rd34, %rd5, %rd33;
    ld.global.f32 %f19, [%rd34];
    add.f32 %f18, %f18, %f19;
    add.u32 %r11, %r11, 1;
    bra FINAL_SUM_LOOP;
FINAL_SUM_END:
    cvt.rn.f32.s32 %f22, %r20;
    div.rn.f32 %f23, %f18, %f22;
    st.global.f32 [%rd4], %f23;
K_EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triplet_margin_kernel")

class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        if not anchor.is_cuda or not positive.is_cuda or not negative.is_cuda:
            raise RuntimeError("All inputs must be CUDA tensors.")
        if anchor.dtype != torch.float32 or positive.dtype != torch.float32 or negative.dtype != torch.float32:
            raise RuntimeError("All inputs must be float32 tensors.")
        if anchor.shape != positive.shape or anchor.shape != negative.shape:
            raise RuntimeError("Input shapes must match.")
        if anchor.dim() != 2:
            raise RuntimeError("Expected inputs of shape (batch, dim).")

        batch_size = anchor.size(0)
        dim_size = anchor.size(1)

        # Allocate output scalar
        out = torch.empty((), device=anchor.device, dtype=anchor.dtype)

        # Kernel launch configuration
        block_x = 64
        grid_x = (batch_size + block_x - 1) // block_x
        grid_x = max(1, grid_x)

        # Temporary buffers
        block_sums = torch.empty(grid_x, device=anchor.device, dtype=anchor.dtype)
        counter = torch.zeros(1, device=anchor.device, dtype=torch.int32)

        module = _get_ptx_module()
        module.launch(
            "triplet_margin_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                anchor.contiguous(),
                positive.contiguous(),
                negative.contiguous(),
                out,
                block_sums,
                counter,
                i32(batch_size),
                i32(dim_size),
                f32(self.margin),
                f32(1.0e-6),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )
        return out

