    .param .u64 pos_ptr,
    .param .u64 neg_ptr,
    .param .u64 out_ptr,
    .param .u64 block_sums_ptr,
    .param .u64 counter_ptr,
    .param .u32 batch_size,
    .param .u32 dim_size,
