    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %nctaid.x;
    // gtid = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32 %r4, %r1, %r2, %r0;
    // stride = blockDim.x * gridDim.x
    mul.lo.u32 %r5, %r2, %r3;
    // Local accumulator
    mov.f32 %f0, 0f00000000;
