LOOP_I:
    setp.ge.u32 %p0, %r4, %r20;
    @%p0 bra LOOP_I_END;
    // base offset in elements = i * dim_size
    mul.wide.u32 %rd10, %r4, %r21;      // 64-bit product
    shl.b64 %rd11, %rd10, 2;            // bytes offset ( *4 )
    add.s64 %rd12, %rd1, %rd11;         // ptrA
