    shr.u32 %r22, %r21, 3;              // vec8 iters = dim >> 3
    shr.u32 %r30, %r21, 2;              // temp for rem vec4
    and.b32 %r30, %r30, 1;              // rem_vec4 = (dim >> 2) & 1
    and.b32 %r23, %r21, 3;              // rem_scalar = dim & 3
    // Dual accumulators for better ILP
    mov.f32 %f25, 0f00000000;           // sumAP_a
