    sub.f32 %f17, %f3, %f11;
    fma.rn.f32 %f27, %f17, %f17, %f27;
    sub.f32 %f16, %f4, %f8;
    fma.rn.f32 %f25, %f16, %f16, %f25;
    sub.f32 %f17, %f4, %f12;
    fma.rn.f32 %f27, %f17, %f17, %f27;
    sub.f32 %f16, %f5, %f9;
    fma.rn.f32 %f25, %f16, %f16, %f25;
    sub.f32 %f17, %f5, %f13;
    fma.rn.f32 %f27, %f17, %f17, %f27;
    sub.f32 %f16, %f6, %f10;
    fma.rn.f32 %f25, %f16, %f16, %f25;
    sub.f32 %f17, %f6, %f14;
    fma.rn.f32 %f27, %f17, %f17, %f27;
    add.s64 %rd12, %rd12, 16;
