    sub.f32 %f17, %f3, %f11;
    fma.rn.f32 %f28, %f17, %f17, %f28;
    sub.f32 %f16, %f4, %f8;
    fma.rn.f32 %f26, %f16, %f16, %f26;
    sub.f32 %f17, %f4, %f12;
    fma.rn.f32 %f28, %f17, %f17, %f28;
    sub.f32 %f16, %f5, %f9;
    fma.rn.f32 %f26, %f16, %f16, %f26;
