    ld.global.cs.v4.f32 {%f11,%f12,%f13,%f14}, [%rd14];     // n tail v4
    sub.f32 %f16, %f3, %f7;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f3, %f11;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    sub.f32 %f16, %f4, %f8;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f4, %f12;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    sub.f32 %f16, %f5, %f9;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f5, %f13;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    sub.f32 %f16, %f6, %f10;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f6, %f14;
    fma.rn.f32 %f2, %f17, %f17, %f2;
