_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triplet_margin_kernel")

class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        if not anchor.is_cuda or not positive.is_cuda or not negative.is_cuda:
            raise RuntimeError("All inputs must be CUDA tensors.")
        if anchor.dtype != torch.float32 or positive.dtype != torch.float32 or negative.dtype != torch.float32:
            raise RuntimeError("All inputs must be float32 tensors.")
        if anchor.shape != positive.shape or anchor.shape != negative.shape:
            raise RuntimeError("Input shapes must match.")
        if anchor.dim() != 2:
            raise RuntimeError("Expected inputs of shape (batch, dim).")

        batch_size = anchor.size(0)
        dim_size = anchor.size(1)

        # Allocate output scalar
        out = torch.empty((), device=anchor.device, dtype=anchor.dtype)

        # Kernel launch configuration
        block_x = 64
        grid_x = (batch_size + block_x - 1) // block_x
        grid_x = max(1, grid_x)

        # Temporary buffers
        block_sums = torch.empty(grid_x, device=anchor.device, dtype=anchor.dtype)
        counter = torch.zeros(1, device=anchor.device, dtype=torch.int32)

        module = _get_ptx_module()
        module.launch(
            "triplet_margin_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                anchor.contiguous(),
                positive.contiguous(),
                negative.contiguous(),
                out,
                block_sums,
                counter,
                i32(batch_size),
                i32(dim_size),
                f32(self.margin),
                f32(1.0e-6),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )
        return out
